let rawList = [];
for (const entry of $input.all()) {
  if (entry.json && Array.isArray(entry.json.places)) {
    rawList.push(...entry.json.places);
  } else if (Array.isArray(entry.json)) {
    rawList.push(...entry.json);
  } else if (entry.json && Array.isArray(entry.json.data)) {
    rawList.push(...entry.json.data);
  } else if (entry.json) {
    rawList.push(entry.json);
  }
}

let minReviews = 1;
let searchQuery = 'Roofers in Solihull, UK';
try {
  const config = $('2. Search Settings').first().json;
  if (config && config.min_reviews !== undefined) {
    minReviews = Number(config.min_reviews);
  }
  if (config && config.search_query) {
    searchQuery = config.search_query;
  }
} catch (e) {}

function getTradeNoun(category, query, name) {
  const combined = ((category || '') + ' ' + (query || '') + ' ' + (name || '')).toLowerCase();
  if (combined.includes('roof')) return 'roofer';
  if (combined.includes('dent') || combined.includes('implant') || combined.includes('smile')) return 'dentist';
  if (combined.includes('account') || combined.includes('tax') || combined.includes('bookkeep')) return 'accountant';
  if (combined.includes('carpent') || combined.includes('joiner')) return 'carpenter';
  if (combined.includes('plumb') || combined.includes('drain') || combined.includes('heat')) return 'plumber';
  if (combined.includes('electric')) return 'electrician';
  if (combined.includes('build') || combined.includes('construct') || combined.includes('loft') || combined.includes('extension')) return 'builder';
  if (combined.includes('cake') || combined.includes('baker') || combined.includes('confection')) return 'baker';
  if (combined.includes('clean')) return 'cleaner';
  if (combined.includes('landscap') || combined.includes('tree') || combined.includes('garden')) return 'landscaper';
  if (combined.includes('paint') || combined.includes('decorat')) return 'decorator';
  return 'tradesperson';
}

function getSpecificIssue(rawWebsite) {
  if (!rawWebsite) return 'the site is currently inaccessible';
  const w = rawWebsite.toLowerCase();
  if (w.includes('facebook.com')) return 'it only points to a Facebook page';
  if (w.includes('instagram.com')) return 'it only directs to an Instagram profile without a quote intake';
  if (w.includes('yell.com') || w.includes('checkatrade.com')) return 'it only links back to a shared directory listing';
  return 'the site failed to open properly';
}

const qualifiedLeads = [];

for (const data of rawList) {
  const rawWebsite = (data.website || '').trim();
  const rawPhone = (data.phoneNumber || data.phone || data.phoneUnformatted || '').trim();
  const totalScore = Number(data.rating || data.totalScore || 0);
  const reviewsCount = Number(data.ratingCount || data.reviewsCount || 0);
  const businessName = data.title || data.name || 'Local Business';
  const address = (data.address || data.city || '').trim() || (searchQuery.replace(/^Roofers in /i, '').replace(/, UK/i, '') || 'UK Regional');
  const categoryName = data.type || data.category || data.categoryName || '';

  if (!rawPhone) continue;
  if (reviewsCount < minReviews) continue;

  const isSocialOrEmpty =
    !rawWebsite ||
    rawWebsite === '' ||
    rawWebsite.includes('facebook.com') ||
    rawWebsite.includes('instagram.com') ||
    rawWebsite.includes('yell.com') ||
    rawWebsite.includes('checkatrade.com');

  if (!isSocialOrEmpty) continue;

  let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (cleanPhone.startsWith('0')) {
    cleanPhone = '+44' + cleanPhone.substring(1);
  }

  const isMobile = cleanPhone.startsWith('+447');
  const channel = isMobile ? 'WhatsApp / SMS' : 'Landline / Direct Call';
  const waDigits = cleanPhone.replace('+', '');
  const waLink = isMobile ? `https://wa.me/${waDigits}?text=${encodeURIComponent('Hi 👋')}` : 'N/A';

  const classification = (!rawWebsite || rawWebsite === '') ? 'no_website' : 'social_only';
  const tradeNoun = getTradeNoun(categoryName, searchQuery, businessName);
  const specificIssue = getSpecificIssue(rawWebsite);

  const stage1Opener = 'Hi 👋';

  const stage2Pitch = classification === 'no_website'
    ? `Came across ${businessName} — had a look for a website, couldn't find one. Here's the bit that actually matters: every day someone searches for a ${tradeNoun} near them, sees you're not there, and books with whoever showed up instead. That's not a maybe — it's happening right now, on jobs you'll never even know you lost.\n\nI build the site before I ever ask for money — I don't sell direction I haven't already shown. If it's not for you, no pressure at all, just glad I flagged it. If it is, we take it from there.`
    : `Came across ${businessName} — went to check out the site, but ${specificIssue}. That's not just a rough edge — it's the exact moment someone decides you're not worth the call, and picks the next result instead. Happening on repeat, quietly, without you ever seeing it.\n\nI build the site before I ever ask for money — I don't sell direction I haven't already shown. If it's not for you, no pressure at all, just glad I flagged it. If it is, we take it from there.`;

  const followUp1 = `Hey — following up on ${businessName}'s site. No pressure at all, just wanted to check it landed and see where you're at.`;
  const followUpFinal = `Last one from me on this — if it's not a priority right now, that's completely fair. If it ever is, the offer stands, just say the word.`;
  const followUpComeBack = `No rush at all — happy to wait until you're ready. Just didn't want it to go unsaid: every day without it is a day someone's landing somewhere else instead of you. Whenever you're ready, everything's exactly as we left it.`;
  const followUpDeclined = `No worries at all, appreciate you letting me know 👍 If that ever changes, feel free to reach out — all the best with the business!`;

  qualifiedLeads.push({
    json: {
      "Business Name": businessName,
      "Phone": cleanPhone,
      "Channel": channel,
      "WhatsApp Link": waLink,
      "Reviews": reviewsCount,
      "Rating": totalScore,
      "Website": rawWebsite || 'None',
      "Address": address,
      "Trade": tradeNoun,
      "Classification": classification,
      "Stage 1 Opener": stage1Opener,
      "Stage 2 Pitch": stage2Pitch,
      "Follow Up 1": followUp1,
      "Follow Up Final": followUpFinal,
      "Follow Up Come Back": followUpComeBack,
      "Follow Up Declined": followUpDeclined,
      "Status": 'Ready to Send'
    }
  });
}

return qualifiedLeads;
